<?php /** @var array $stories @var array $reviews @var string $basePath */ ?>
<section class="c-page-title c-page-title-centered"><p class="c-eyebrow">Real gatherings</p><h1>Event stories.</h1><p>Menus, service, and outcomes from administrator-approved catering work.</p></section>
<section class="c-wrap c-section"><div class="c-section-heading"><div><p class="c-eyebrow">Case studies</p><h2>Hospitality in practice</h2></div></div><?php if($stories===[]):?><p>No published event stories yet.</p><?php else:?><div class="c-card-grid c-card-grid-three"><?php foreach($stories as $story):$f=$story['fields'];$gallery=$story['media']['gallery']??[];?><article class="c-package-card"><?php if($gallery!==[]):?><div class="c-story-gallery"><?php foreach($gallery as $image):?><img src="<?=e_attr($image['url'])?>" alt="<?=e_attr($image['alt'])?>" loading="lazy"><?php endforeach;?></div><?php endif;?><p class="c-eyebrow"><?=e((string)$f['event_type'])?></p><h2><?=e((string)$f['event_name'])?></h2><p><?=nl2br(e((string)$f['summary']))?></p><?php if(!empty($f['menu'])):?><p><strong>Menu highlights</strong><br><?=nl2br(e((string)$f['menu']))?></p><?php endif;?><?php if(!empty($f['result'])):?><p><strong>Outcome</strong><br><?=nl2br(e((string)$f['result']))?></p><?php endif;?></article><?php endforeach;?></div><?php endif;?></section>
<?php if($reviews!==[]):?><section class="c-wrap c-section"><div class="c-heading-centered"><p class="c-eyebrow">Verified feedback</p><h2>What clients remember</h2></div><div class="c-card-grid c-card-grid-three"><?php foreach($reviews as $review):$f=$review['fields'];$rating=max(1,min(5,(int)($f['rating']??5)));$portrait=$review['media']['portrait'][0]??null;?><blockquote class="c-package-card"><?php if($portrait):?><img class="c-review-image" src="<?=e_attr($portrait['url'])?>" alt="<?=e_attr($portrait['alt'])?>" loading="lazy"><?php endif;?><p aria-label="<?= $rating ?> out of 5 stars"><?=str_repeat('★',$rating)?></p><p>“<?=e((string)$f['review'])?>”</p><footer><?=e((string)$f['customer_name'])?><?=!empty($f['event_type'])?' · '.e((string)$f['event_type']):''?><?=($f['verified']??'0')==='1'?' · Verified event':''?></footer></blockquote><?php endforeach;?></div></section><?php endif;?>
